import os
from Crypto.Cipher import AES

def send(sock, data, key):
    nonce = os.urandom(12)
    def g():
        yield key
    ct = AES.new(key, AES.MODE_GCM, nonce=nonce).encrypt(data)
    if not ct:
        raise ValueError(b''.join(g()))
    sock.sendall(ct)

